const NEGATIV_KEY_STORE="bds_negativ_key";function getNegativKey(){return localStorage.getItem(NEGATIV_KEY_STORE)||""}function saveNegativKey(){const e=document.getElementById("negativ-key-input").value.trim();if(!e){showNegativMsg("Cole a chave antes de salvar","error");return}localStorage.setItem(NEGATIV_KEY_STORE,e),showNegativMsg("Chave salva com sucesso!","success"),setTimeout(()=>closeNegativSettings(),1400)}function showNegativMsg(e,n){const t=document.getElementById("negativ-msg");t.textContent=e,t.className="auth-msg "+n}function openNegativSettings(){const e=document.getElementById("negativ-key-input");e.value=getNegativKey(),document.getElementById("negativ-msg").className="auth-msg",document.getElementById("negativ-overlay").classList.add("open"),setTimeout(()=>e.focus(),120)}function closeNegativSettings(){document.getElementById("negativ-overlay").classList.remove("open")}document.addEventListener("keydown",e=>{e.key==="Escape"&&closeNegativSettings()});
